CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "channels" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('channels', 'id', 'id', 'name', 'private', 'created_by', 'summary', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "invites" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('invites', 'id', 'id', 'channel_id', 'invited_by', 'email', 'status', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "memberships" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('memberships', 'id', 'id', 'channel_id', 'user_id', 'last_read_at', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "messages" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('messages', 'id', 'id', 'channel_id', 'author_id', 'body', 'client_key', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "tasks" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('tasks', 'id', 'id', 'channel_id', 'title', 'column', 'position', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "tips" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('tips', 'id', 'id', 'from_id', 'to_id', 'amount', 'status', 'receipt', 'reason', 'attempt', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "users" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('users', 'id', 'id', 'name', 'email', 'is_admin', 'signed_out_at', 'created_at');

CREATE CONSTRAINT TRIGGER "seal" AFTER INSERT ON "live"."pending" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "live"."seal"();

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "rpc"."inbox" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('rpc.inbox', 'id', 'id', 'account', 'title', 'body', 'link', 'action', 'kind', 'read_at', 'created_at');

CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "rpc"."jobs" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('rpc.jobs', 'id', 'id', 'key', 'name', 'queue', 'arguments', 'owner', 'viewer', 'visibility', 'serial_key', 'state', 'attempts', 'max_attempts', 'priority', 'run_at', 'deadline_at', 'started_at', 'finished_at', 'locked_until', 'result', 'error', 'progress', 'fraction', 'steps', 'cancel_requested', 'failure_pending', 'created_at');
